/**
 * @event
 * @name scwin.btn_searchFind_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchFind_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchFind_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchFind()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45203.btn_searchFind_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_kpageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_kpageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_kpageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_kpageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.briefPopView === 'function') { await scwin.briefPopView(r["disclsBriefPublIsu"]); } else { console.error('[sdd] 행 동작 미정의: scwin.briefPopView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.briefPopView'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_kpageList.oncellclick' });
    }
};

