 * @name scwin.searchFind
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchFind = async function () {
    /* sdd-asis-lifecycle:begin fn_searchFind — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchFindReq').set('pageNum', $c.util.getComponent("dma_searchFindReq").get("pageIndex"));
    scwin.form_searchFrm.action = '/main/search.do';
    $c.util.getComponent("dma_searchFindReq").set("method", 'searchDataReference');
    await scwin.tx_fn_searchFind();
    /* sdd-asis-lifecycle:end */
};


